1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: grid; place-items: center;
11	    background: #eef0f3; font-family: system-ui, -apple-system, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 92vw); padding: 16px; border-radius: 16px;
15	    background: #1f2329; box-shadow: 0 10px 30px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 72px; margin-bottom: 12px; padding: 0 12px; border-radius: 10px;
19	    background: #2c323a; color: #fff; font-size: 2.2rem;
20	    display: flex; align-items: center; justify-content: flex-end;
21	    overflow: hidden; white-space: nowrap;
22	  }
23	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
24	  button {
25	    height: 60px; border: 0; border-radius: 10px; font-size: 1.3rem;
26	    background: #3a414b; color: #fff; cursor: pointer;
27	  }
28	  button:active { filter: brightness(1.2); }
29	  .op { background: #f59e0b; }
30	  .clear { background: #6b7280; }
31	  .equals { background: #10b981; }
32	  .wide { grid-column: span 2; }
33	</style>
34	</head>
35	<body>
36	<div class="calc">
37	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
38	  <div class="keys">
39	    <button class="clear wide" data-testid="key-lparen" data-action="lparen">(</button>
40	    <button class="clear wide" data-testid="key-rparen" data-action="rparen">)</button>
41	    <button class="clear wide" data-testid="key-clear" data-action="clear">AC</button>
42	    <button class="clear" data-testid="key-sign" data-action="sign">±</button>
43	    <button class="op" data-testid="key-div" data-op="/">÷</button>
44	    <button data-testid="key-7" data-digit="7">7</button>
45	    <button data-testid="key-8" data-digit="8">8</button>
46	    <button data-testid="key-9" data-digit="9">9</button>
47	    <button class="op" data-testid="key-mul" data-op="*">×</button>
48	    <button data-testid="key-4" data-digit="4">4</button>
49	    <button data-testid="key-5" data-digit="5">5</button>
50	    <button data-testid="key-6" data-digit="6">6</button>
51	    <button class="op" data-testid="key-sub" data-op="-">−</button>
52	    <button data-testid="key-1" data-digit="1">1</button>
53	    <button data-testid="key-2" data-digit="2">2</button>
54	    <button data-testid="key-3" data-digit="3">3</button>
55	    <button class="op" data-testid="key-add" data-op="+">+</button>
56	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
57	    <button data-testid="key-dot" data-action="dot">.</button>
58	    <button class="equals" data-testid="key-equals" data-action="equals">=</button>
59	  </div>
60	</div>
61	<script>
62	  // State: acc = stored left operand, op = pending operator,
63	  // entry = digits being typed (string) or null, value = number shown,
64	  // ready = value is a finished right operand made by ± or ), not typed,
65	  // groups = saved { acc, op } of each open parenthesis, innermost last.
66	  var state = { acc: null, op: null, entry: null, value: 0, error: false, ready: false, groups: [] };
67	
68	  function compute(a, op, b) {
69	    var r;
70	    if (op === '+') r = a + b;
71	    else if (op === '-') r = a - b;
72	    else if (op === '*') r = a * b;
73	    else r = a / b;
74	    if (!isFinite(r)) return NaN;
75	    return r;
76	  }
77	
78	  // Presentation only: stored values are never rounded. At most 10 significant
79	  // digits, no trailing zeros, exponential only for |n| >= 1e10 or < 1e-9.
80	  function formatNumber(n) {
81	    if (n === 0) return '0';
82	    var r = Number(n.toPrecision(10));
83	    var abs = Math.abs(r);
84	    if (abs >= 1e10 || abs < 1e-9) {
85	      return r.toExponential(9).replace(/\.?0+e/, 'e');
86	    }
87	    var exp = Number(r.toExponential(9).split('e')[1]);
88	    var s = r.toFixed(Math.max(0, 9 - exp));
89	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
90	    return s;
91	  }
92	
93	  function pressDigit(d) {
94	    if (state.error) return;
95	    state.ready = false;
96	    if (state.entry === null || state.entry === '0') state.entry = d;
97	    else if (state.entry === '-0') state.entry = '-' + d;
98	    else state.entry += d;
99	    state.value = Number(state.entry);
100	  }
101	
102	  function pressDot() {
103	    if (state.error) return;
104	    state.ready = false;
105	    if (state.entry === null) state.entry = '0';
106	    if (state.entry.indexOf('.') === -1) state.entry += '.';
107	    state.value = Number(state.entry);
108	  }
109	
110	  // While typing, ± toggles the sign of the typed digits so typing can go on.
111	  // Otherwise it flips the shown value; with an operator waiting, that value
112	  // becomes the right operand (5 + ± = is 0).
113	  function pressSign() {
114	    if (state.error) return;
115	    if (state.entry !== null) {
116	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
117	      state.value = Number(state.entry);
118	    } else {
119	      state.value = -state.value;
120	      state.ready = state.op !== null;
121	    }
122	  }
123	
124	  function resolve() {
125	    if (state.op !== null && (state.entry !== null || state.ready)) {
126	      state.value = compute(state.acc, state.op, state.value);
127	      if (isNaN(state.value)) state.error = true;
128	    }
129	  }
130	
131	  // Immediate execution, no precedence: each operator key first finishes the
132	  // waiting operation, strictly left to right, so the display always shows a
133	  // real running result. 2 + 3 × 4 = is 20, not 14.
134	  function pressOp(op) {
135	    if (state.error) return;
136	    resolve();
137	    if (state.error) return;
138	    state.acc = state.value;
139	    state.op = op;
140	    state.entry = null;
141	    state.ready = false;
142	  }
143	
144	  // ( saves the waiting operation and starts a fresh one inside the group.
145	  // Inside, the same left-to-right rule applies.
146	  function pressLparen() {
147	    if (state.error) return;
148	    state.groups.push({ acc: state.acc, op: state.op });
149	    state.acc = null;
150	    state.op = null;
151	    state.entry = null;
152	    state.value = 0;
153	    state.ready = false;
154	  }
155	
156	  // ) finishes the group; its result becomes the right operand of the saved
157	  // operation (2 + ( 3 × 4 ) = is 14). Ignored with no open group.
158	  function closeGroup() {
159	    resolve();
160	    if (state.error) return;
161	    var g = state.groups.pop();
162	    state.acc = g.acc;
163	    state.op = g.op;
164	    state.entry = null;
165	    state.ready = state.op !== null;
166	  }
167	
168	  function pressRparen() {
169	    if (state.error || state.groups.length === 0) return;
170	    closeGroup();
171	  }
172	
173	  // = closes any open groups first.
174	  function pressEquals() {
175	    if (state.error) return;
176	    while (state.groups.length > 0 && !state.error) closeGroup();
177	    if (state.error) return;
178	    resolve();
179	    state.acc = null;
180	    state.op = null;
181	    state.entry = null;
182	    state.ready = false;
183	  }
184	
185	  function clear() {
186	    state = { acc: null, op: null, entry: null, value: 0, error: false, ready: false, groups: [] };
187	  }
188	
189	  var display = document.querySelector('[data-testid="calc-display"]');
190	
191	  function render() {
192	    display.setAttribute('data-value', String(state.value));
193	    display.setAttribute('data-error', state.error ? 'true' : 'false');
194	    if (state.error) display.textContent = 'Error';
195	    else display.textContent = state.entry !== null ? state.entry : formatNumber(state.value);
196	  }
197	
198	  document.querySelector('.keys').addEventListener('click', function (e) {
199	    var b = e.target.closest('button');
200	    if (!b) return;
201	    if (b.dataset.digit !== undefined) pressDigit(b.dataset.digit);
202	    else if (b.dataset.op) pressOp(b.dataset.op);
203	    else if (b.dataset.action === 'dot') pressDot();
204	    else if (b.dataset.action === 'sign') pressSign();
205	    else if (b.dataset.action === 'lparen') pressLparen();
206	    else if (b.dataset.action === 'rparen') pressRparen();
207	    else if (b.dataset.action === 'equals') pressEquals();
208	    else if (b.dataset.action === 'clear') clear();
209	    render();
210	  });
211	
212	  render();
213	</script>
214	</body>
215	</html>
